#!/bin/bash
# Battle Tanks: Seeker Edition v0.5.0 - Self-extracting APK installer
# Run: bash install-battle-tanks.sh

APK_FILE="battle-tanks-seeker.apk"
echo "=== Battle Tanks: Seeker Edition v0.5.0 ==="
echo "Extracting APK..."

base64 -d << 'APK_BASE64' > "$APK_FILE"

APK_BASE64

if [ -f "$APK_FILE" ]; then
    SIZE=$(wc -c < "$APK_FILE")
    echo "APK extracted: $APK_FILE ($SIZE bytes)"
    echo ""
    echo "To install:"
    echo "  adb install $APK_FILE"
    echo ""
    echo "Or transfer to your device and open the file."
else
    echo "ERROR: Failed to extract APK"
    exit 1
fi
